import { readFile } from 'node:fs/promises';
import path from 'node:path';
import { canonicalSha256 } from '../core/canonical-json.mjs';
import { loadCapabilityGraphV2 } from '../capabilities/v2/compiler.mjs';
import { loadBuiltInProviders } from '../federation/local-provider-seed.mjs';
import { routeSkillIntelligence } from './router.mjs';
import { createDefaultTokenAccountingRegistry } from '../context/token-accounting.mjs';
import { loadSkillSections } from '../skills/v2/section-index.mjs';
import { compileGlobalContext } from '../context/context-compiler.mjs';
import { compileScope } from '../fabric/scope-compiler.mjs';
import { loadUniversalLaneRegistry } from './universal-lanes.mjs';

const loadJson=async(file)=>JSON.parse(await readFile(file,'utf8'));
export class SkillIntelligenceService{
 #root;#graph=null;#providers=null;#catalog=null;#registry;
 constructor({root=process.cwd(),tokenRegistry=createDefaultTokenAccountingRegistry()}={}){this.#root=path.resolve(root);this.#registry=tokenRegistry;}
 async #state(){if(!this.#graph)this.#graph=await loadCapabilityGraphV2(path.join(this.#root,'capabilities-v2/graph.json'));if(!this.#providers)this.#providers=await loadBuiltInProviders(path.join(this.#root,'providers/built-in-providers.json'));if(!this.#catalog)this.#catalog=await loadJson(path.join(this.#root,'skills-v2/catalog.json'));return{graph:this.#graph,providers:this.#providers,catalog:this.#catalog};}
 async status(){const{graph,providers}=await this.#state();const procedural=providers.filter((item)=>item.kind==='skill');return{outcomeCount:graph.outcomes.length,techniqueCount:graph.techniques.length,l0TechniqueCount:graph.techniques.filter((item)=>item.kernelLevel==='L0').length,l1TechniqueCount:graph.techniques.filter((item)=>item.kernelLevel==='L1').length,kernelTechniqueCount:graph.techniques.filter((item)=>['L0','L1'].includes(item.kernelLevel)).length,evaluatorCount:graph.evaluators.length,providerCount:providers.length,stableProceduralProviders:procedural.filter((item)=>item.status==='stable').length,candidateProceduralProviders:procedural.filter((item)=>item.status==='candidate').length,graphSha256:graph.graphSha256};}

 async universalLanes(){return loadUniversalLaneRegistry({root:this.#root});}

 async search(query,{limit=20}={}){const{catalog}=await this.#state();const terms=String(query??'').toLowerCase().normalize('NFKC').replace(/[^\p{L}\p{N}]+/gu,' ').trim().split(/\s+/).filter(Boolean);const results=[];for(const entry of catalog){const manifest=await loadJson(path.join(this.#root,entry.path,'manifest.json'));const hay=[manifest.id,manifest.identity.title,manifest.identity.description,...manifest.identity.keywords,...manifest.identity.domains,...manifest.identity.subdomains].join(' ').toLowerCase();const matched=terms.filter((term)=>hay.includes(term));if(!matched.length)continue;const score=matched.length/Math.max(1,terms.length)+(manifest.maturity==='stable'?0.2:0)+(manifest.kernelLevel==='L0'?0.05:0);results.push({id:manifest.id,title:manifest.identity.title,description:manifest.identity.description,maturity:manifest.maturity,skillType:manifest.skillType,kernelLevel:manifest.kernelLevel??null,domains:manifest.identity.domains,targetTokens:manifest.context.targetTokens,manifestSha256:manifest.manifestSha256,score:Number(score.toFixed(6))});}return results.sort((a,b)=>b.score-a.score||a.id.localeCompare(b.id)).slice(0,Math.max(1,Math.min(100,Number(limit)||20)));}
 async auditStableMaterialization({model='gpt-5.6'}={}){const{providers}=await this.#state();const ids=[...new Set(providers.filter((item)=>item.kind==='skill'&&item.status==='stable').map((item)=>item.providerId.replace(/^local-skill\./,'')))].sort();const failures=[];let passed=0;for(const skillId of ids){try{await this.materialize({skillId,model});passed++;}catch(error){failures.push({skillId,error:error.message});}}return{total:ids.length,passed,failed:failures.length,failures};}
  async route(args){const{graph,providers}=await this.#state();return routeSkillIntelligence({graph,providers,intent:{query:args.query,domains:args.domains??[],taskClass:args.taskClass??'generic',targetOutcomeIds:args.targetOutcomeIds??[],maxOutcomes:args.maxOutcomes},context:{model:args.model??'gpt-5.6',tools:args.tools??[],assurance:args.assurance??'A1',allowExternal:args.allowExternal===true,operation:args.operation??'routine',routeBudgetTokens:args.routeBudgetTokens}});}
 async #entry(skillId){const{catalog}=await this.#state();const entry=catalog.find((item)=>item.id===skillId);if(!entry)throw new Error(`Unknown Skill Contract v2 package: ${skillId}`);const manifest=await loadJson(path.join(this.#root,entry.path,'manifest.json'));if(canonicalSha256({...manifest,manifestSha256:null})!==manifest.manifestSha256)throw new Error(`Skill manifest digest mismatch: ${skillId}`);return{entry,manifest,root:path.join(this.#root,entry.path)};}
 async inspect(skillId){const{manifest}=await this.#entry(skillId);return{id:manifest.id,version:manifest.version,maturity:manifest.maturity,skillType:manifest.skillType,kernelLevel:manifest.kernelLevel??null,manifestSha256:manifest.manifestSha256,identity:manifest.identity,context:manifest.context,sections:manifest.sectionIndex.sections.map(({id,path,sha256,bytes,tokens})=>({id,path,sha256,bytes,tokens})),policyProfileHashes:manifest.policyProfileHashes,capabilityMappings:manifest.capabilityMappings,evaluatorPackage:manifest.evaluatorPackage};}
 async materialize({skillId,sections,model='gpt-5.6',hardTokens}){const{manifest,root}=await this.#entry(skillId);if(!['stable','certified'].includes(manifest.maturity))throw new Error(`Skill ${skillId} is ${manifest.maturity}; only stable or certified packages may be materialized`);const sectionIds=sections?.length?sections:manifest.context.defaultSections;const loaded=await loadSkillSections(root,manifest.sectionIndex,{sectionIds,model,hardTokens:Math.min(Number(hardTokens??manifest.context.hardTokens),manifest.context.hardTokens),registry:this.#registry});const subject={schemaVersion:2,skillId,manifestSha256:manifest.manifestSha256,model,sections:loaded.sections.map((item)=>({id:item.id,sha256:item.sha256,tokens:item.tokens,content:item.content})),tokens:loaded.tokens,text:loaded.text,omitted:loaded.omitted};return{...subject,contextPackSha256:canonicalSha256(subject)};}
 async compileContext(args){return compileGlobalContext({model:args.model??'gpt-5.6',policy:args.policy,tokenRegistry:this.#registry,inputs:args.inputs??{}});}
 scope(args){return compileScope({change:{files:args.files??[]},policy:{include:args.include??['**'],exclude:args.exclude??[]}});}
 async evaluationManifest(skillId){const{manifest,root}=await this.#entry(skillId);const [cases,baseline]=await Promise.all([loadJson(path.join(root,manifest.evaluatorPackage.cases)),loadJson(path.join(root,manifest.evaluatorPackage.baseline))]);return{schemaVersion:2,skillId,maturity:manifest.maturity,evaluatorIds:manifest.verification.evaluatorIds,publicCaseCount:cases.length,publicCaseIds:cases.map((item)=>item.id).sort(),publicCasesSha256:canonicalSha256(cases),baselineStatus:baseline.status,holdout:{vendored:false,disclosure:'hash-and-aggregate-only'}};}
}
